package com.crms.controller;import com.crms.repository.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/placements") public class PlacementController{private final ApplicationRepository apps;public PlacementController(ApplicationRepository a){apps=a;}@GetMapping("/my")public List<?> mine(){return apps.findAll().stream().filter(a->a.getStatus()==com.crms.enums.ApplicationStatus.SELECTED).toList();}}
